    n = len(grid)
    half = n // 2
    tl = [row[:half] for row in grid[:half]]
    tr = [row[half:] for row in grid[:half]]
    bl = [row[:half] for row in grid[half:]]
    br = [row[half:] for row in grid[half:]]
    return tl, tr, bl, br, n

